import sympy

def build_instance(rng):
    coefficient_a = rng.randint(1, 8)
    constant_b = rng.randint(-9, 9)
    constant_c = rng.randint(-9, 9)
    equation = f'{coefficient_a}x + {constant_b} = {constant_c}'
    x = sympy.symbols('x')
    solution = sympy.solve(coefficient_a * x + constant_b - constant_c, x)
    answer = len(solution)
    check = 1 if coefficient_a != 0 else 0
    parameters = {'coefficient_a': coefficient_a, 'constant_b': constant_b, 'constant_c': constant_c}
    return (parameters, answer, check)



